CREATE TABLE "public"."categories" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "slug"       text,
  "title"      text,
  CONSTRAINT "categories_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."categories"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."colors" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "slug"       text,
  "title"      text,
  "value"      text,
  CONSTRAINT "colors_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."colors"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."post_authors" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"       text,
  "slug"       text,
  "avatar"     text,
  "bio"        text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "post_authors_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."post_authors"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."post_categories" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title"      text,
  "slug"       text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "post_categories_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."post_categories"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."post_tag_relations" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "post_id"    uuid,
  "tag_id"     bigint,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "post_tag_relations_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."post_tag_relations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."post_tags" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "slug"       text,
  "title"      text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "post_tags_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."post_tags"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."posts" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "title"        text,
  "slug"         text                     NOT NULL,
  "excerpt"      text,
  "content"      text,
  "category_id"  bigint,
  "status"       text,
  "published_at" timestamp with time zone,
  "post_image"   text,
  "post_banner"  text,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "author_id"    uuid                     DEFAULT gen_random_uuid(),
  CONSTRAINT "posts_pkey" PRIMARY KEY (id),
  CONSTRAINT "posts_slug_key" UNIQUE (slug)
);

ALTER TABLE "public"."posts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."product_variants" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "product_id" uuid,
  "size_id"    bigint,
  "color_id"   bigint,
  "price"      bigint,
  "stock"      integer,
  "sku"        text,
  CONSTRAINT "product_variants_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."product_variants"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."products" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "slug"         text,
  "title"        text,
  "score"        numeric,
  "comment_num"  bigint,
  "introduction" text,
  "material"     text,
  "type_use"     text,
  "category_id"  bigint,
  "images"       text[]                   DEFAULT '{}'::text[],
  "sales_count"  bigint,
  CONSTRAINT "products_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."products"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sizes" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "slug"        text,
  "title"       text,
  "category_id" bigint,
  CONSTRAINT "sizes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."sizes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."users" (
  "id"         uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "first_name" text,
  "last_name"  text,
  "phone"      text,
  "avatar_url" text,
  CONSTRAINT "users_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."users"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."post_tag_relations"
  ADD CONSTRAINT "post_tag_relations_tag_id_fkey" FOREIGN KEY (tag_id) REFERENCES public.post_tags(id);

ALTER TABLE "public"."posts"
  ADD CONSTRAINT "posts_author_id_fkey" FOREIGN KEY (author_id) REFERENCES public.post_authors(id);

ALTER TABLE "public"."posts"
  ADD CONSTRAINT "posts_category_id_fkey" FOREIGN KEY (category_id) REFERENCES public.post_categories(id);

ALTER TABLE "public"."post_tag_relations"
  ADD CONSTRAINT "post_tag_relations_post_id_fkey" FOREIGN KEY (post_id) REFERENCES public.posts(id);

ALTER TABLE "public"."product_variants"
  ADD CONSTRAINT "product_variants_color_id_fkey" FOREIGN KEY (color_id) REFERENCES public.colors(id);

ALTER TABLE "public"."products"
  ADD CONSTRAINT "products_category_id_fkey" FOREIGN KEY (category_id) REFERENCES public.categories(id);

ALTER TABLE "public"."product_variants"
  ADD CONSTRAINT "product_variants_product_id_fkey" FOREIGN KEY (product_id) REFERENCES public.products(id);

ALTER TABLE "public"."sizes"
  ADD CONSTRAINT "sizes_category_id_fkey" FOREIGN KEY (category_id) REFERENCES public.categories(id);

ALTER TABLE "public"."product_variants"
  ADD CONSTRAINT "product_variants_size_id_fkey" FOREIGN KEY (size_id) REFERENCES public.sizes(id);

ALTER TABLE "public"."users"
  ADD CONSTRAINT "users_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id);

CREATE POLICY "anyone can view posts" ON "public"."posts"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "anyone can view products variants" ON "public"."product_variants"
  FOR SELECT
  TO PUBLIC
  USING (true);

CREATE POLICY "Anyone can view products" ON "public"."products"
  FOR SELECT
  TO PUBLIC
  USING (true);

ALTER PUBLICATION "supabase_realtime" ADD TABLE "public"."products";

